void UAlsAnimationInstance::RefreshView(const float DeltaTime)
{
	if (!LocomotionAction.IsValid())
	{
		ViewState.YawAngle = FMath::UnwindDegrees(UE_REAL_TO_FLOAT(
			ViewState.RotationWorldSpace.Yaw - LocomotionState.RotationWorldSpace.Yaw));

		ViewState.PitchAngle = FMath::UnwindDegrees(UE_REAL_TO_FLOAT(
			ViewState.RotationWorldSpace.Pitch - LocomotionState.RotationWorldSpace.Pitch));

		ViewState.PitchAmount = 0.5f - ViewState.PitchAngle / 180.0f;
	}

	const auto ViewAmount{1.0f - GetCurveValueClamped01(UAlsConstants::ViewBlockCurveName())};
	const auto AimingAmount{GetCurveValueClamped01(UAlsConstants::PoseAimingCurveName())};

void UAlsAnimationInstance::RefreshHead()
{
#if WITH_EDITOR
	if (!IsValid(GetWorld()) || !GetWorld()->IsGameWorld())
	{
		return;
	}
#endif

	DECLARE_SCOPE_CYCLE_COUNTER(TEXT("UAlsAnimationInstance::RefreshHead"), STAT_UAlsAnimationInstance_RefreshHead, STATGROUP_Als)
	TRACE_CPUPROFILER_EVENT_SCOPE_STR(__FUNCTION__)

	if (!IsValid(Settings))
	{
		return;
	}

	const auto DeltaTime{GetDeltaSeconds()};
	const auto bFirstPerson{ViewMode == AlsViewModeTags::FirstPerson};

	if (MovementBase.bHasRelativeRotation)
	{
		// Offset the angle to keep it in the movement base space.
		HeadState.YawAngle += UE_REAL_TO_FLOAT(MovementBase.DeltaRotation.Yaw);
	}

	// Offset the angle to make it independent of character rotation.
	HeadState.YawAngle -= LocomotionState.YawVelocityWorldSpace * DeltaTime;

	// Clamp the angle instead of using FMath::UnwindDegrees() so that the head does not suddenly change the look side.
	HeadState.YawAngle = FMath::Clamp(HeadState.YawAngle, -180.0f, 180.0f);

	float TargetPitchAngle;
	float TargetYawAngle;
	auto bReadyToSwitchLookSides{false};

	if (RotationMode == AlsRotationModeTags::VelocityDirection)
	{
		// Look towards input direction.

		TargetPitchAngle = 0.0f;

		TargetYawAngle = FMath::UnwindDegrees(UE_REAL_TO_FLOAT(
			(LocomotionState.bHasInput ? LocomotionState.InputYawAngleWorldSpace : LocomotionState.TargetYawAngleWorldSpace) -
			LocomotionState.RotationWorldSpace.Yaw));

		static constexpr auto LocomotionYawSpeedThreshold{20.0f};

		if (FMath::Abs(LocomotionState.YawVelocityWorldSpace) > LocomotionYawSpeedThreshold)
		{
			// Favor the character rotation direction, over the shortest rotation direction, so
			// that the rotation of the head remains synchronized with the rotation of the body.

			TargetYawAngle = FMath::Sign(LocomotionState.YawVelocityWorldSpace) * FMath::Abs(TargetYawAngle);
		}
		else if (FMath::Abs(TargetYawAngle) > 180.0f - UAlsRotation::CounterClockwiseRotationAngleThreshold)
		{
			// Do not rotate the head if the character is going to turn 180 degrees, or it may start rotating in the wrong direction.
			TargetYawAngle = HeadState.YawAngle;
		}

		HeadState.bSwitchingLookSides = false;
	}
	else
	{
		// Look towards view direction.

		TargetPitchAngle = ViewState.PitchAngle;
		TargetYawAngle = ViewState.YawAngle;

		// Keep the target angle in the [-175, 175] range, as the character often
		// tends to break his neck when the target angle is close to 180 degrees.

		TargetYawAngle = FMath::Clamp(TargetYawAngle,
		                              -180.0f + UAlsRotation::CounterClockwiseRotationAngleThreshold,
		                              180.0f - UAlsRotation::CounterClockwiseRotationAngleThreshold);

		if (!bFirstPerson)
		{
			static constexpr auto SwitchSidesCurrentYawAngleThreshold{90.0f};
			static constexpr auto SwitchSidesTargetYawAngleThreshold{160.0f};

			if (HeadState.YawAngle >= SwitchSidesCurrentYawAngleThreshold &&
			    TargetYawAngle <= -SwitchSidesTargetYawAngleThreshold)
			{
				// Keep the target angle at 175 degrees if the character is looking at an angle greater than 90 degrees,
				// and the target angle less than -160 degrees to prevent the character from switching look sides too often.

				TargetYawAngle = 180.0f - UAlsRotation::CounterClockwiseRotationAngleThreshold;
				bReadyToSwitchLookSides = !LocomotionState.bHasInput;
			}
			else if (HeadState.YawAngle <= -SwitchSidesCurrentYawAngleThreshold &&
			         TargetYawAngle >= SwitchSidesTargetYawAngleThreshold)
			{
				TargetYawAngle = -180.0f + UAlsRotation::CounterClockwiseRotationAngleThreshold;
				bReadyToSwitchLookSides = !LocomotionState.bHasInput;
			}
		}
	}

	if (HeadState.bInitializationRequired)
	{
		HeadState.bInitializationRequired = false;

		HeadState.PitchAngle = TargetPitchAngle;
		HeadState.YawAngle = TargetYawAngle;
		HeadState.YawVelocity = 0.0f;
		HeadState.bSwitchingLookSides = false;
	}
	else
	{
		// Use real-time delta time in first-person mode. Otherwise, if slow motion is active
		// and the player quickly rotates the camera, it may intersect the skeletal mesh.

		const auto EffectiveDeltaTime{bFirstPerson ? DeltaTimeWithoutTimeDilation : DeltaTime};

		HeadState.PitchAngle = UAlsRotation::DamperExactAngle(HeadState.PitchAngle, TargetPitchAngle, EffectiveDeltaTime,
		                                                      bFirstPerson
			                                                      ? Settings->Head.FirstPersonPitchAngleInterpolationHalfLife
			                                                      : Settings->Head.PitchAngleInterpolationHalfLife);

		if (bReadyToSwitchLookSides)
		{
			HeadState.bSwitchingLookSides = true;
		}
		else
		{
			const auto DeltaYawAngle{FMath::UnwindDegrees(TargetYawAngle - HeadState.YawAngle)};
			if (FMath::Abs(DeltaYawAngle) <= 10.0f)
			{
				// Consider the switching completed if the current angle is close to the target.
				HeadState.bSwitchingLookSides = false;
			}
		}

		// Use the exact critical spring damper as it provides smooth head rotation. Use a
		// different smoothing time when switching sides for even smoother head rotation.
		// https://theorangeduck.com/page/spring-roll-call#critical

		const auto SmoothingTime{
			SpringMath::HalfLifeToSmoothingTime(HeadState.bSwitchingLookSides
				                                    ? Settings->Head.SwitchLookSidesYawAngleInterpolationHalfLife
				                                    : bFirstPerson
				                                    ? Settings->Head.FirstPersonYawAngleInterpolationHalfLife
				                                    : Settings->Head.YawAngleInterpolationHalfLife)
		};

		SpringMath::CriticalSpringDamper(HeadState.YawAngle, HeadState.YawVelocity, TargetYawAngle, SmoothingTime, DeltaTime);
	}

	HeadState.YawAmount = HeadState.YawAngle / 360.0f + 0.5f;

//			 https://theorangeduck.com/page/fitting-code-driven-displacement
//			 https://theorangeduck.com/page/fitting-code-driven-displacement-revisited

struct SpringMath
{
private:
	static constexpr float SmoothingTimeToDamping(float SmoothingTime)
	{
		return 4.0f / FMath::Max(SmoothingTime, UE_SMALL_NUMBER);
	}

}

/** Convert a halflife to a smoothing time
 * 
 * @param HalfLife The half life of the spring. How long it takes the value to get halfway towards the target.
 * @return The smoothing time of the spring in seconds. It is the time by which the output lags the input when critically damped, when the input is changing at a constant rate.
 */
static constexpr float HalfLifeToSmoothingTime(float HalfLife)
{
	return HalfLife / UE_LN2;
}

/** Convert from smoothing time to spring strength.
  * 
 * @param SmoothingTime The smoothing time of the spring in seconds. It is the time by which the output lags the input when critically damped, when the input is changing at a constant rate.
 * @return The spring strength. This corresponds to the undamped frequency of the spring in hz.

static void CriticalSpringDamper(
	T& InOutX,
	T& InOutV,
	T TargetX,
	float SmoothingTime,
	float DeltaTime)
{
	if (SmoothingTime < UE_SMALL_NUMBER)
	{
		InOutX = TargetX;
		InOutV = T(0);
		return;
	}

	float Y = SmoothingTimeToDamping(SmoothingTime) / 2.0f;
	T J0 = InOutX - TargetX;
	T J1 = InOutV + J0 * Y;
	float EyDt = FMath::InvExpApprox(Y * DeltaTime);

	InOutX = EyDt * (J0 + J1 * DeltaTime) + TargetX;
	InOutV = EyDt * (InOutV - J1 * Y * DeltaTime);
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct AlsHeadSettings {
    pub pitch_half_life: f32,
    pub yaw_half_life: f32,
    pub switch_look_sides_yaw_half_life: f32,
    pub first_person_pitch_half_life: f32,
    pub first_person_yaw_half_life: f32,
}

impl Default for AlsHeadSettings {
    fn default() -> Self {
        Self {
            pitch_half_life: 0.1,
            yaw_half_life: 0.1,
            switch_look_sides_yaw_half_life: 0.2,
            first_person_pitch_half_life: 0.01,
            first_person_yaw_half_life: 0.01,
        }

pub fn damper_exact_angle(current: f32, target: f32, delta_seconds: f32, half_life: f32) -> f32 {
    let mut delta = unwind_degrees(target - current);
    if delta.abs() <= 1e-4 {
        return target;
    }
    if delta > 175.0 {
        delta -= 360.0;
    }
    let alpha =
        1.0 - inv_exp_approx(std::f32::consts::LN_2 * delta_seconds.max(0.0) / (half_life + 1e-8));
    unwind_degrees(current + delta * alpha)
}

pub fn critical_spring_damper(
    current: f32,
    velocity: &mut f32,
    target: f32,
    delta_seconds: f32,
    half_life: f32,
) -> f32 {
    let smoothing_time = half_life / std::f32::consts::LN_2;
    if smoothing_time < 1e-8 {
        *velocity = 0.0;
        return target;
    }
    let y = 2.0 / smoothing_time.max(1e-8);
    let j0 = current - target;
    let j1 = *velocity + j0 * y;
    let e = inv_exp_approx(y * delta_seconds.max(0.0));
    let result = e * (j0 + j1 * delta_seconds.max(0.0)) + target;
    *velocity = e * (*velocity - j1 * y * delta_seconds.max(0.0));
    result
}

pub fn update_head_state(
    state: &mut AlsHeadState,
    input: AlsHeadUpdateInput,
    settings: AlsHeadSettings,
) {
    if input.movement_base_relative_yaw != 0.0 {
        state.yaw_angle += input.movement_base_relative_yaw;
    }
    state.yaw_angle -= input.body_yaw_velocity_world * input.delta_seconds;
    state.yaw_angle = state.yaw_angle.clamp(-180.0, 180.0);
    let mut ready_to_switch_look_sides = false;
    let (target_pitch, target_yaw) = if input.rotation_mode == RotationMode::VelocityDirection {
        let mut target_yaw = unwind_degrees(
            (if input.has_input {
                input.input_yaw_world
            } else {
                input.target_yaw_world
            }) - input.body_yaw_world,
        );
        if input.body_yaw_velocity_world.abs() > LOCOMOTION_YAW_SPEED_THRESHOLD {
            target_yaw = input.body_yaw_velocity_world.signum() * target_yaw.abs();
        } else if target_yaw.abs() > 180.0 - COUNTER_CLOCKWISE_ROTATION_ANGLE_THRESHOLD {
            target_yaw = state.yaw_angle;
        }
        state.switching_look_sides = false;
        (0.0, target_yaw)
    } else {
        let mut target_yaw = input.view_yaw_angle.clamp(
            -180.0 + COUNTER_CLOCKWISE_ROTATION_ANGLE_THRESHOLD,
            180.0 - COUNTER_CLOCKWISE_ROTATION_ANGLE_THRESHOLD,
        );
        if !input.first_person {
            if state.yaw_angle >= SWITCH_SIDES_CURRENT_YAW_THRESHOLD
                && target_yaw <= -SWITCH_SIDES_TARGET_YAW_THRESHOLD
            {
                target_yaw = 180.0 - COUNTER_CLOCKWISE_ROTATION_ANGLE_THRESHOLD;
                ready_to_switch_look_sides = !input.has_input;
            } else if state.yaw_angle <= -SWITCH_SIDES_CURRENT_YAW_THRESHOLD
                && target_yaw >= SWITCH_SIDES_TARGET_YAW_THRESHOLD
            {
                target_yaw = -180.0 + COUNTER_CLOCKWISE_ROTATION_ANGLE_THRESHOLD;
                ready_to_switch_look_sides = !input.has_input;
            }
        }
        (input.view_pitch_angle, target_yaw)
    };
    if state.initialization_required {
        state.initialization_required = false;
        state.pitch_angle = target_pitch;
        state.yaw_angle = target_yaw;
        state.yaw_velocity = 0.0;
        state.switching_look_sides = false;
    } else {
        let effective_delta_seconds = if input.first_person {
            input.delta_seconds_without_time_dilation
        } else {
            input.delta_seconds
        };
        state.pitch_angle = damper_exact_angle(
            state.pitch_angle,
            target_pitch,
            effective_delta_seconds,
            if input.first_person {
                settings.first_person_pitch_half_life
            } else {
                settings.pitch_half_life
            },
        );
        if ready_to_switch_look_sides {
            state.switching_look_sides = true;
        } else if unwind_degrees(target_yaw - state.yaw_angle).abs()
            <= SWITCH_SIDES_COMPLETE_YAW_DELTA
        {
            state.switching_look_sides = false;
        }
        state.yaw_angle = critical_spring_damper(
            state.yaw_angle,
            &mut state.yaw_velocity,
            target_yaw,
            input.delta_seconds,
            if state.switching_look_sides {
                settings.switch_look_sides_yaw_half_life
            } else if input.first_person {
                settings.first_person_yaw_half_life
            } else {
                settings.yaw_half_life
            },
        );
    }
    state.yaw_amount = state.yaw_angle / 360.0 + 0.5;

let view_degrees = crate::als::turn_in_place::wrap_angle_degrees(view_yaw.0.to_degrees());
let previous_view = player
